import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { canonical, checkAppearance, tileId, tileIds } from "./helpers/appearance-reference.mjs";

// Step 3 of specs/006-shared-model/plan.md (SM3, #47): vectors for `puzlwerk.appearance` revision 1,
// contract specs/001-core-foundation/contracts/appearance-v1.md. The vectors are generated by
// scripts/appearance-examples.mjs; this test reads them with the reference reader of the helper.
const dir = new URL("./fixtures/appearance/", import.meta.url);
const raw = (n, d = dir) => readFileSync(new URL(n, d), "utf8");
const json = (n, d = dir) => JSON.parse(raw(n, d));
const wire = new URL("./fixtures/wire/", import.meta.url);
const defs = { "definition-2.json": json("definition-2.json", wire), "definition-3.json": json("definition-3.json", wire) };
const index = json("index.json");
const contract = readFileSync(new URL("../specs/001-core-foundation/contracts/appearance-v1.md", import.meta.url), "utf8");

test("every example is canonical and has the recorded size and SHA-256", () => {
  assert.deepEqual(Object.keys(index), ["cubacle-2.json", "image-256.json", "invalid.json", "picture-2.json", "picture-3.json", "tint-3.json"]);
  for (const [name, { bytes, sha256 }] of Object.entries(index)) {
    const text = raw(name);
    assert.equal(text, canonical(JSON.parse(text)), `${name} is canonical`);
    assert.equal(Buffer.byteLength(text), bytes, `${name} bytes`);
    assert.equal("sha256:" + createHash("sha256").update(text, "utf8").digest("hex"), sha256, `${name} hash`);
  }
});

test("canonical form sorts keys at every depth and keeps array order", () => {
  assert.equal(canonical({ b: [3, { y: 1, x: "a" }], a: null }), `{"a":null,"b":[3,{"x":"a","y":1}]}`);
});

test("tile IDs equal the Cubistry Picture Cube 3x3 tiles for all 54 cells", () => {
  const oracle = json("tiles-3.oracle.json").tiles;
  const FRAME = { U: [[0, 1, 0], [0, 0, -1]], D: [[0, -1, 0], [0, 0, 1]], F: [[0, 0, 1], [0, 1, 0]], B: [[0, 0, -1], [0, 1, 0]], L: [[-1, 0, 0], [0, 1, 0]], R: [[1, 0, 0], [0, 1, 0]] };
  assert.equal(Object.keys(oracle).length, 54);
  for (const [tile, p] of Object.entries(oracle)) {
    const [normal, up] = FRAME[tile[0]];
    assert.equal(tileId(3, p.map((v) => 2 * v), normal, up), tile);
  }
  // Every sticker of the 3x3 definition gets a distinct tile, and the tiles are exactly the 54 oracle tiles.
  assert.deepEqual([...tileIds(defs["definition-3.json"]).values()].sort(), Object.keys(oracle).sort());
});

test("tile IDs of the 2x2 definition by hand (top-left cell of each face, and F_0_1, U_1_1)", () => {
  const t = tileIds(defs["definition-2.json"]);
  const expect = { "UFL.F": "F_0_0", "UFR.F": "F_0_1", "UBL.U": "U_0_0", "UFR.U": "U_1_1", "UFR.R": "R_0_0", "UBR.B": "B_0_0", "DFL.D": "D_0_0", "UBL.L": "L_0_0" };
  for (const [sticker, tile] of Object.entries(expect)) assert.equal(t.get(sticker), tile, sticker);
  assert.equal(new Set(t.values()).size, 24);
});

test("valid examples are read; their facts match the sources", () => {
  const cases = { "picture-2.json": "definition-2.json", "picture-3.json": "definition-3.json", "tint-3.json": "definition-3.json", "cubacle-2.json": "definition-2.json", "image-256.json": "definition-2.json" };
  for (const [name, def] of Object.entries(cases)) assert.deepEqual(checkAppearance(defs[def], json(name)), { ok: true }, name);
  const p3 = json("picture-3.json");
  assert.equal(p3.stickers.length, 54);
  assert.deepEqual(p3.stickers.filter((s) => s.symmetry).map((s) => [s.id, s.image, s.symmetry]), [["F.F", "F_1_1", "C2"], ["U.U", "U_1_1", "C4"]]);
  // Rubik-Tint: the color follows the home face of the sticker (cubistry HOME_ORIENTATION).
  const tint = json("tint-3.json");
  assert.equal(tint.stickers.find((s) => s.id === "UF.F").color, "tint-white");
  assert.equal(tint.stickers.find((s) => s.id === "UF.U").color, "tint-blue");
  assert.equal(tint.stickers.find((s) => s.id === "DR.D").color, "tint-green");
  assert.equal(new Set(tint.stickers.map((s) => s.color)).size, 6);
  // Cubacle `image`: opaque, not tile IDs, so the document does not declare imageIds.
  const cu = json("cubacle-2.json");
  assert.equal("imageIds" in cu, false);
  assert.equal(cu.stickers.find((s) => s.id === "DBL.B").image, "0:2");
});

test("each invalid vector fails with its code at its path", () => {
  const bad = json("invalid.json");
  assert.equal(bad.length, 20);
  for (const v of bad) {
    const r = checkAppearance(defs[v.definition], v.document);
    assert.deepEqual([r.ok, r.code, r.path], [false, v.code, v.path], v.name);
  }
});

test("the contract names every error code of the vectors, the tile rule, and wire-v1", () => {
  for (const code of new Set(json("invalid.json").map((v) => v.code))) assert.ok(contract.includes("`" + code + "`"), code);
  for (const phrase of ["`puzlwerk.appearance`", "`tile-v1`", "<face>_<row>_<col>", "C1", "C2", "C4", "wire-v1"]) assert.ok(contract.includes(phrase), phrase);
});
